-- Wetlands: creature abilities
-- The Cataclysm creatures of the Wetlands (Dragonmaw, Mosshide, Bluegill, the Dark Iron at Thandol Span, the cursed sailors, the
-- wildlife, elementals and oozes) had no AI, and the Cataclysm data does not script them either, but their sniffed spell lists are in
-- creature_template spell1-8: cast those. The Dragonmaw of Grim Batol's approach take their Cataclysm abilities, and Tapoke "Slim"
-- Jahn and Comar Villard their classic ones.

SET @ENTRIES := '1036,1038,1057,1476,4971,5683';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '41072,41080,41132,41137,41145,41147,41151,41167,41272,41293,41295,41342,41343,41388,41389,41390,41391,41394,41400,41401,41409,41416,41419,41420,41424,41425,41426,41427,41428,41429,41449,41453,41522,41524,41553,41556,41558,41613,42041,42042,42043,42107,42110,42111,42154,42577,44110,44116,44224,44225,44226,44227,46122,48535,51520,51844,51922';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
